#include <iostream>
#include <vector>
#include <utility>

using namespace std;

constexpr int MOD = 1'000'000'007;

struct Matrix {
    int rows, cols;
    vector<int> data;

    Matrix(int r, int c) : rows(r), cols(c), data(static_cast<size_t>(r) * c, 0) {}

    int& operator()(int r, int c) {
        return data[static_cast<size_t>(r) * cols + c];
    }

    int operator()(int r, int c) const {
        return data[static_cast<size_t>(r) * cols + c];
    }
};

Matrix multiply(const Matrix& a, const Matrix& b) {
    Matrix c(a.rows, b.cols);

    for (int i = 0; i < a.rows; ++i) {
        for (int k = 0; k < a.cols; ++k) {
            if (a(i, k) == 0) continue;

            const long long x = a(i, k);
            for (int j = 0; j < b.cols; ++j) {
                if (b(k, j) == 0) continue;
                c(i, j) = (c(i, j) + x * b(k, j)) % MOD;
            }
        }
    }

    return c;
}

Matrix power(Matrix base, long long exponent) {
    Matrix result(base.rows, base.cols);
    for (int i = 0; i < base.rows; ++i) {
        result(i, i) = 1;
    }

    while (exponent > 0) {
        if (exponent & 1LL) {
            result = multiply(result, base);
        }
        exponent >>= 1LL;
        if (exponent > 0) {
            base = multiply(base, base);
        }
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int m;
    cin >> n >> m;

    if (n < m) {
        cout << 1 << '\n';
        return 0;
    }

    if (n == m) {
        cout << 2 << '\n';
        return 0;
    }

    Matrix dp(1, m);
    for (int i = 0; i < m; ++i) {
        dp(0, i) = (i == m - 1 ? 2 : 1);
    }

    Matrix transition(m, m);
    transition(0, m - 1) = 1;
    transition(m - 1, m - 1) = 1;

    for (int i = m - 2; i >= 0; --i) {
        transition(i + 1, i) = 1;
    }

    transition = power(std::move(transition), n - m);
    Matrix answer = multiply(dp, transition);

    cout << answer(0, m - 1) << '\n';
    return 0;
}

